-- PADGREF 24/10 SQL 154 : placements FIXES des monstres dans 35 salles de boss (liste de l'utilisateur, ordre modulaire :
-- un palier prend les lignes jusqu'à lui ; CellId -1 = case non donnée -> placement normal). Lu à chaque combat (Fight.PlacerPlacementFixe).
CREATE TABLE IF NOT EXISTS padgref_placements_fixes (DungeonSpawnId INT NOT NULL, Rang INT NOT NULL, MonsterId INT NOT NULL, CellId INT NOT NULL, PRIMARY KEY (DungeonSpawnId, Rang)) DEFAULT CHARSET=utf8;
DELETE FROM padgref_placements_fixes WHERE DungeonSpawnId IN (300,301,332,333,312,319,510,359,339,349,354,389,9714,428,443,418,398,384,9719,374,379,423,413,390,369,9709,408,433,438,364,391,9704,403,396,397);
